IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE LOWER(conname) = LOWER('FK_change_notification_rec_notification_id_id')
    ) THEN
    ALTER TABLE change_notification_rec ADD CONSTRAINT FK_change_notification_rec_notification_id_id FOREIGN KEY (notification_id) REFERENCES change_notification (id);
END IF;
END$$;
;
